[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">

  <!-- Primary Meta Tags -->
  <title>WellSource — Expert health guidance you can trust</title>
  <meta name="title" content="WellSource — Expert health guidance you can trust">
  <meta name="description" content="WellSource delivers medically reviewed health content, tools, and resources to empower informed health decisions. Trusted by 55 million monthly readers.">

  <!-- Canonical URL -->
  <link rel="canonical" href="https://www.wellsource.com/">

  <!-- Open Graph / Facebook -->
  <meta property="og:type" content="website">
  <meta property="og:url" content="https://www.wellsource.com/">
  <meta property="og:title" content="WellSource — Expert health guidance you can trust">
  <meta property="og:description" content="WellSource delivers medically reviewed health content, tools, and resources to empower informed health decisions. Trusted by 55 million monthly readers.">
  <meta property="og:image" content="https://www.wellsource.com/og-image.jpg">

  <!-- Twitter -->
  <meta property="twitter:card" content="summary_large_image">
  <meta property="twitter:url" content="https://www.wellsource.com/">
  <meta property="twitter:title" content="WellSource — Expert health guidance you can trust">
  <meta property="twitter:description" content="WellSource delivers medically reviewed health content, tools, and resources to empower informed health decisions. Trusted by 55 million monthly readers.">
  <meta property="twitter:image" content="https://www.wellsource.com/og-image.jpg">

  <!-- Favicons -->
  <link rel="icon" type="image/svg+xml" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><text y='.9em' font-size='90'>+</text></svg>">

  <!-- Structured Data: Organization -->
  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "Organization",
    "name": "WellSource",
    "url": "https://www.wellsource.com",
    "description": "WellSource is a comprehensive health and wellness media platform delivering medically reviewed content, tools, and resources to empower informed health decisions.",
    "@id": "https://www.wellsource.com/#organization",
    "sameAs": [
      "https://www.facebook.com/WellSource",
      "https://x.com/WellSource",
      "https://www.pinterest.com/WellSource",
      "https://www.instagram.com/WellSource",
      "https://www.youtube.com/WellSource"
    ],
    "foundingDate": "2005",
    "contactPoint": {
      "@type": "ContactPoint",
      "contactType": "customer service",
      "url": "https://www.wellsource.com/contact"
    }
  }
  </script>

  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">

  <style>
    /* ===== RESET & BASE ===== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --teal: #02838D;
      --teal-dark: #016770;
      --teal-light: #E6F4F6;
      --teal-lighter: #F2F9FA;
      --charcoal: #231F20;
      --white: #FFFFFF;
      --warm-white: #FAFAF8;
      --gray-50: #F9F9F7;
      --gray-100: #F0F0ED;
      --gray-200: #E5E5E1;
      --gray-300: #D4D4CF;
      --gray-400: #A0A09A;
      --gray-500: #6B6B65;
      --gray-600: #4A4A45;
      --coral: #E8614D;
      --coral-light: #FDF0ED;
      --amber: #F0A04B;
      --amber-light: #FEF7EF;
      --green-50: #EDF7F0;
      --text: #231F20;
      --text-secondary: #4A4A45;
      --text-muted: #6B6B65;
      --radius-sm: 8px;
      --radius: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
      --shadow: 0 4px 12px rgba(0,0,0,0.06);
      --shadow-lg: 0 8px 30px rgba(0,0,0,0.08);
      --transition: 0.2s ease;
    }

    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: var(--text);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }
    a { color: inherit; text-decoration: none; }
    ul { list-style: none; }
    img { max-width: 100%; display: block; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    input { font-family: inherit; }

    .container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
    .container--narrow { max-width: 1100px; }

    /* ===== TOP BAR ===== */
    .topbar {
      background: var(--charcoal);
      color: var(--white);
      font-size: 13px;
      padding: 8px 0;
    }
    .topbar .container { display: flex; justify-content: flex-end; align-items: center; gap: 20px; }
    .topbar a { color: var(--gray-300); transition: color var(--transition); }
    .topbar a:hover { color: var(--white); }
    .topbar .btn-signin {
      background: var(--teal);
      color: var(--white);
      padding: 6px 16px;
      border-radius: 20px;
      font-weight: 500;
      font-size: 13px;
      transition: background var(--transition);
    }
    .topbar .btn-signin:hover { background: var(--teal-dark); }

    /* ===== HEADER ===== */
    .header {
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      position: sticky;
      top: 0;
      z-index: 100;
    }
    .header .container {
      display: flex;
      align-items: center;
      height: 64px;
      gap: 32px;
    }
    .header__logo {
      font-size: 26px;
      font-weight: 800;
      color: var(--teal);
      letter-spacing: -0.5px;
      white-space: nowrap;
    }
    .header__logo span { color: var(--charcoal); }
    .header__nav { display: flex; gap: 4px; flex: 1; }
    .header__nav > li { position: relative; }
    .header__nav > li > button {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 8px 14px;
      font-size: 15px;
      font-weight: 500;
      color: var(--text);
      border-radius: var(--radius-sm);
      transition: all var(--transition);
    }
    .header__nav > li > button:hover,
    .header__nav > li.active > button {
      color: var(--teal);
      background: var(--teal-lighter);
    }
    .header__nav > li > button .chevron {
      width: 16px;
      height: 16px;
      transition: transform var(--transition);
    }
    .header__nav > li.active > button .chevron {
      transform: rotate(180deg);
    }
    .header__search {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 14px;
      border: 1px solid var(--gray-200);
      border-radius: 24px;
      color: var(--gray-400);
      font-size: 14px;
      transition: all var(--transition);
      width: 200px;
    }
    .header__search:hover, .header__search:focus-within {
      border-color: var(--teal);
      box-shadow: 0 0 0 3px rgba(2,131,141,0.08);
    }
    .header__search input {
      border: none;
      outline: none;
      font-size: 14px;
      flex: 1;
      color: var(--text);
      background: transparent;
    }
    .header__search input::placeholder { color: var(--gray-400); }

    /* ===== MEGA MENU ===== */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      padding: 28px 32px;
      min-width: 640px;
      display: none;
      z-index: 200;
    }
    .header__nav > li.active .mega-menu { display: block; }
    .mega-menu__grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 8px 24px;
    }
    .mega-menu__grid--cols2 { grid-template-columns: repeat(2, 1fr); }
    .mega-menu__col h4 {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: var(--gray-400);
      margin-bottom: 10px;
      grid-column: 1 / -1;
    }
    .mega-menu a {
      display: block;
      padding: 6px 10px;
      font-size: 14px;
      color: var(--text-secondary);
      border-radius: 6px;
      transition: all var(--transition);
      white-space: nowrap;
    }
    .mega-menu a:hover {
      background: var(--teal-lighter);
      color: var(--teal);
    }

    /* ===== CREDIBILITY TICKER ===== */
    .credibility-ticker {
      background: var(--teal-light);
      border-bottom: 1px solid rgba(2,131,141,0.1);
      overflow: hidden;
      padding: 10px 0;
    }
    .credibility-ticker__inner {
      display: flex;
      gap: 48px;
      animation: ticker-scroll 20s linear infinite;
      width: max-content;
    }
    .credibility-ticker__item {
      display: flex;
      align-items: center;
      gap: 10px;
      white-space: nowrap;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
    }
    .credibility-ticker__icon {
      width: 20px;
      height: 20px;
      color: var(--teal);
      flex-shrink: 0;
    }
    @keyframes ticker-scroll {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    /* ===== HERO ===== */
    .hero {
      padding: 60px 0;
      background: linear-gradient(135deg, var(--warm-white) 0%, var(--white) 100%);
    }
    .hero .container { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
    .hero__badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--amber-light);
      color: #B8751A;
      font-size: 13px;
      font-weight: 600;
      padding: 6px 14px;
      border-radius: 20px;
      margin-bottom: 20px;
    }
    .hero__badge svg { width: 16px; height: 16px; }
    .hero__category {
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1.2px;
      color: var(--teal);
      margin-bottom: 12px;
    }
    .hero__title {
      font-size: 44px;
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -1px;
      color: var(--charcoal);
      margin-bottom: 16px;
    }
    .hero__subtitle {
      font-size: 18px;
      color: var(--text-secondary);
      line-height: 1.6;
      margin-bottom: 28px;
      max-width: 480px;
    }
    .hero__cta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--teal);
      color: var(--white);
      font-size: 16px;
      font-weight: 600;
      padding: 14px 28px;
      border-radius: 28px;
      transition: all var(--transition);
    }
    .hero__cta:hover { background: var(--teal-dark); transform: translateY(-1px); box-shadow: var(--shadow); }
    .hero__image {
      background: linear-gradient(135deg, #D4EDF0 0%, #B8E0E4 50%, #E8D5C4 100%);
      border-radius: var(--radius-xl);
      aspect-ratio: 4/3;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }
    .hero__image-inner {
      text-align: center;
      color: var(--teal-dark);
    }
    .hero__image-inner svg { width: 120px; height: 120px; opacity: 0.6; }

    /* ===== TRENDING SIDEBAR ===== */
    .trending-section {
      padding: 0 0 56px 0;
      background: var(--white);
    }
    .trending-section .container { display: grid; grid-template-columns: 2fr 1fr; gap: 40px; }
    .trending__sidebar {
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      padding: 28px 24px;
      border: 1px solid var(--gray-100);
    }
    .trending__sidebar h3 {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 20px;
      color: var(--charcoal);
    }
    .trending__list { display: flex; flex-direction: column; gap: 16px; }
    .trending__item { display: flex; gap: 12px; align-items: flex-start; }
    .trending__item-num {
      font-size: 28px;
      font-weight: 800;
      color: var(--gray-200);
      line-height: 1;
      flex-shrink: 0;
    }
    .trending__item-content .trending__cat {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      color: var(--teal);
      margin-bottom: 2px;
    }
    .trending__item-content a {
      font-size: 15px;
      font-weight: 500;
      color: var(--text);
      line-height: 1.4;
      transition: color var(--transition);
    }
    .trending__item-content a:hover { color: var(--teal); }

    /* ===== NEWSLETTER CTA ===== */
    .newsletter-cta {
      padding: 48px 0;
      background: linear-gradient(135deg, var(--teal) 0%, #016770 100%);
      color: var(--white);
    }
    .newsletter-cta .container {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 40px;
      align-items: center;
    }
    .newsletter-cta h2 {
      font-size: 32px;
      font-weight: 800;
      letter-spacing: -0.5px;
      line-height: 1.2;
      margin-bottom: 12px;
    }
    .newsletter-cta p {
      font-size: 16px;
      opacity: 0.85;
      line-height: 1.6;
      margin-bottom: 20px;
    }
    .newsletter-cta__form {
      display: flex;
      gap: 10px;
      max-width: 440px;
    }
    .newsletter-cta__form input {
      flex: 1;
      padding: 14px 18px;
      border-radius: 28px;
      border: 2px solid transparent;
      font-size: 15px;
      outline: none;
      transition: all var(--transition);
    }
    .newsletter-cta__form input:focus { border-color: var(--amber); box-shadow: 0 0 0 4px rgba(240,160,75,0.2); }
    .newsletter-cta__form button {
      padding: 14px 28px;
      background: var(--amber);
      color: var(--white);
      font-size: 15px;
      font-weight: 600;
      border-radius: 28px;
      transition: all var(--transition);
      white-space: nowrap;
    }
    .newsletter-cta__form button:hover { background: #E08F35; transform: translateY(-1px); }
    .newsletter-cta__privacy {
      font-size: 12px;
      opacity: 0.6;
      margin-top: 10px;
    }

    /* ===== SECTION HEADERS ===== */
    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 28px;
    }
    .section-header h2 {
      font-size: 28px;
      font-weight: 800;
      letter-spacing: -0.5px;
      color: var(--charcoal);
    }
    .section-header__link {
      font-size: 14px;
      font-weight: 600;
      color: var(--teal);
      display: flex;
      align-items: center;
      gap: 4px;
      transition: color var(--transition);
    }
    .section-header__link:hover { color: var(--teal-dark); }

    /* ===== HEALTH TOPICS CAROUSEL ===== */
    .health-topics { padding: 56px 0; background: var(--white); }
    .health-topics__carousel { position: relative; }
    .health-topics__track {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      scroll-behavior: smooth;
      scrollbar-width: none;
      padding: 8px 4px 24px;
    }
    .health-topics__track::-webkit-scrollbar { display: none; }
    .health-topics__card {
      flex-shrink: 0;
      width: 160px;
      text-align: center;
      cursor: pointer;
      transition: transform var(--transition);
    }
    .health-topics__card:hover { transform: translateY(-4px); }
    .health-topics__card-img {
      width: 120px;
      height: 120px;
      border-radius: 50%;
      margin: 0 auto 14px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 32px;
      border: 3px solid var(--gray-100);
      transition: all var(--transition);
    }
    .health-topics__card:hover .health-topics__card-img {
      border-color: var(--teal);
      box-shadow: 0 4px 20px rgba(2,131,141,0.15);
    }
    .health-topics__card-label {
      font-size: 14px;
      font-weight: 600;
      color: var(--text);
      line-height: 1.3;
    }
    .health-topics__arrows {
      position: absolute;
      top: 50px;
      left: -12px;
      right: -12px;
      display: flex;
      justify-content: space-between;
      pointer-events: none;
      z-index: 5;
    }
    .health-topics__arrows button {
      pointer-events: all;
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: var(--white);
      border: 1px solid var(--gray-200);
      box-shadow: var(--shadow);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--text-secondary);
      transition: all var(--transition);
    }
    .health-topics__arrows button:hover {
      background: var(--teal);
      color: var(--white);
      border-color: var(--teal);
    }
    .health-topics__arrows button:disabled { opacity: 0.3; cursor: default; }

    /* ===== TOOLS SECTION ===== */
    .tools { padding: 56px 0; background: var(--gray-50); }
    .tools__grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; }
    .tools__hub {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 32px;
      border: 1px solid var(--gray-100);
      transition: box-shadow var(--transition);
    }
    .tools__hub:hover { box-shadow: var(--shadow-lg); }
    .tools__hub-icon {
      width: 48px;
      height: 48px;
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 16px;
    }
    .tools__hub h3 { font-size: 20px; font-weight: 700; margin-bottom: 8px; }
    .tools__hub p { font-size: 14px; color: var(--text-secondary); line-height: 1.6; margin-bottom: 16px; }
    .tools__hub-link {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 14px;
      font-weight: 600;
      color: var(--teal);
      transition: color var(--transition);
    }
    .tools__hub-link:hover { color: var(--teal-dark); }
    .tools__list { display: flex; flex-direction: column; gap: 14px; margin-top: 20px; }
    .tools__list-item {
      display: flex;
      gap: 12px;
      align-items: flex-start;
      padding: 12px;
      border-radius: var(--radius-sm);
      transition: background var(--transition);
      cursor: pointer;
    }
    .tools__list-item:hover { background: var(--gray-50); }
    .tools__list-item-icon {
      width: 36px;
      height: 36px;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      margin-top: 2px;
    }
    .tools__list-item h4 { font-size: 14px; font-weight: 600; margin-bottom: 2px; }
    .tools__list-item p { font-size: 13px; color: var(--text-muted); line-height: 1.4; }

    .tools__drug-list { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
    .tools__drug-card {
      background: var(--white);
      padding: 20px;
      border-radius: var(--radius);
      border: 1px solid var(--gray-100);
      transition: all var(--transition);
      cursor: pointer;
    }
    .tools__drug-card:hover { border-color: var(--teal); box-shadow: var(--shadow-sm); }
    .tools__drug-card h4 { font-size: 15px; font-weight: 600; margin-bottom: 6px; }
    .tools__drug-card p { font-size: 13px; color: var(--text-muted); line-height: 1.5; margin-bottom: 10px; }
    .tools__drug-card .tools__hub-link { font-size: 13px; }

    /* ===== RECOMMENDED READS ===== */
    .recommended-reads { padding: 56px 0; background: var(--white); }
    .recommended-reads__tabs {
      display: flex;
      gap: 4px;
      margin-bottom: 28px;
      border-bottom: 1px solid var(--gray-200);
      padding-bottom: 0;
      overflow-x: auto;
      scrollbar-width: none;
    }
    .recommended-reads__tabs::-webkit-scrollbar { display: none; }
    .recommended-reads__tab {
      padding: 10px 20px;
      font-size: 14px;
      font-weight: 500;
      color: var(--text-secondary);
      border-radius: var(--radius-sm) var(--radius-sm) 0 0;
      border: 1px solid transparent;
      border-bottom: none;
      transition: all var(--transition);
      white-space: nowrap;
    }
    .recommended-reads__tab:hover { color: var(--teal); }
    .recommended-reads__tab.active {
      color: var(--teal);
      font-weight: 600;
      border-color: var(--gray-200);
      background: var(--white);
      margin-bottom: -1px;
    }
    .recommended-reads__grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }
    .recommended-reads__card {
      background: var(--white);
      border: 1px solid var(--gray-100);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: all var(--transition);
      cursor: pointer;
    }
    .recommended-reads__card:hover {
      transform: translateY(-3px);
      box-shadow: var(--shadow-lg);
    }
    .recommended-reads__card-img {
      height: 160px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 40px;
    }
    .recommended-reads__card-body { padding: 18px; }
    .recommended-reads__card-body h4 {
      font-size: 16px;
      font-weight: 600;
      line-height: 1.4;
      color: var(--text);
    }

    /* ===== TRUST PILLARS ===== */
    .trust-pillars { padding: 60px 0; background: var(--teal-lighter); }
    .trust-pillars .section-header { justify-content: center; text-align: center; }
    .trust-pillars .section-header h2 { max-width: 600px; }
    .trust-pillars__grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }
    .trust-pillars__card {
      text-align: center;
      padding: 28px 20px;
      background: var(--white);
      border-radius: var(--radius-lg);
      border: 1px solid var(--gray-100);
      transition: all var(--transition);
    }
    .trust-pillars__card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
    .trust-pillars__card-icon {
      width: 56px;
      height: 56px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
