    }

    /* ===== FEATURED PROGRAMS ===== */
    .featured-programs { padding: 56px 0; background: var(--white); }
    .featured-programs__grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }
    .featured-programs__card {
      border-radius: var(--radius-lg);
      overflow: hidden;
      border: 1px solid var(--gray-100);
      transition: all var(--transition);
      cursor: pointer;
    }
    .featured-programs__card:hover { transform: translateY(-3px); box-shadow: var(--shadow); }
    .featured-programs__card-img {
      height: 140px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 40px;
    }
    .featured-programs__card-body { padding: 18px; }
    .featured-programs__card-body h4 {
      font-size: 15px;
      font-weight: 600;
      line-height: 1.4;
      color: var(--text);
    }

    /* ===== LATEST VIDEOS ===== */
    .latest-videos { padding: 56px 0; background: var(--gray-50); }
    .latest-videos__grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }
    .latest-videos__card {
      background: var(--white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      border: 1px solid var(--gray-100);
      transition: all var(--transition);
      cursor: pointer;
    }
    .latest-videos__card:hover { transform: translateY(-3px); box-shadow: var(--shadow); }
    .latest-videos__card-thumb {
      height: 130px;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
    }
