      line-height: 1.5;
    }
    .footer__newsletter-form {
      display: flex;
      gap: 10px;
      min-width: 340px;
    }
    .footer__newsletter-form input {
      flex: 1;
      padding: 12px 16px;
      border-radius: 24px;
      border: 1px solid var(--gray-500);
      background: rgba(255,255,255,0.08);
      color: var(--white);
      font-size: 14px;
      outline: none;
      transition: border-color var(--transition);
    }
    .footer__newsletter-form input:focus { border-color: var(--teal); }
    .footer__newsletter-form input::placeholder { color: var(--gray-500); }
    .footer__newsletter-form button {
      padding: 12px 24px;
      background: var(--teal);
      color: var(--white);
      font-size: 14px;
      font-weight: 600;
      border-radius: 24px;
      transition: background var(--transition);
      white-space: nowrap;
    }
    .footer__newsletter-form button:hover { background: var(--teal-dark); }
    .footer__links {
      display: flex;
      flex-wrap: wrap;
      gap: 12px 24px;
      margin-bottom: 28px;
    }
    .footer__links a {
      font-size: 14px;
      color: var(--gray-400);
      transition: color var(--transition);
    }
    .footer__links a:hover { color: var(--white); }
    .footer__social { display: flex; gap: 16px; margin-bottom: 28px; }
    .footer__social a {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: rgba(255,255,255,0.08);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      transition: all var(--transition);
    }
    .footer__social a:hover { background: var(--teal); color: var(--white); }
    .footer__legal {
      border-top: 1px solid rgba(255,255,255,0.08);
      padding: 24px 0;
      font-size: 12px;
      color: var(--gray-500);
      line-height: 1.6;
    }

    /* ===== RESPONSIVE ===== */
