      .footer__newsletter { flex-direction: column; align-items: flex-start; }
      .footer__newsletter-form { min-width: 0; width: 100%; }
      .header__search { display: none; }
      .header__nav > li > button { font-size: 13px; padding: 6px 8px; }
      .mega-menu { min-width: 480px; padding: 20px 24px; }
    }

    @media (max-width: 640px) {
